/**
 * obsidian/knowledge/reindexer.ts — orchestrates building and writing the
 * derived vault files generated by `buildKnowledgeGraph`.
 *
 * `VaultReindexer` scans the vault, reads note frontmatter, calls
 * `buildKnowledgeGraph`, then writes ONLY files that changed. It skips
 * files with Windows-invalid names, handles manual INDEX.md files, and
 * enforces an optional deadline.
 *
 * IO boundary: all filesystem access goes through `FilesystemPort`.
 * No `node:` imports; pure TypeScript.
 *
 * # 8 KB partial read
 * `FilesystemPort` does not support partial reads. We read the full file and
 * slice it to at most 8192 bytes before parsing frontmatter. This means we
 * always read the full bytes from disk but only parse the first chunk. The
 * slice is applied to the raw string (not bytes), which is safe for our
 * frontmatter parser since frontmatter always appears at the top of the file.
 *
 * # Deletion of orphaned derived files
 * When a previously-generated hub or index no longer has a corresponding node
 * (e.g. a topic was removed from the vocabulary) we delete it if and only if
 * `isChambaGenerated(path, content)` returns true (never delete human files).
 * `FilesystemPort.remove()` is used for deletion. If deletion fails (e.g.
 * read-only FS), the error is captured and the file is reported as not deleted.
 *
 * # adoptManual
 * `adoptManual: string[]` lists folder paths (e.g. `"informes/"`) whose manual
 * INDEX.md should be renamed to `INDEX (manual).md` and replaced with a
 * generated one. This never happens automatically — only when the option is
 * passed. In dryRun mode the plan is reported but nothing is written.
 */

import type { DirEntry, FilesystemPort } from '../../ports/filesystem.js';
import { isTaskEvidencePath } from '../../tasks/evidence-paths.js';
import { isChambaGenerated, isDerivedPathPattern } from './derived-path.js';
import type { TopicSuggestion } from './knowledge-graph.js';
import { buildKnowledgeGraph, computeSuggestions } from './knowledge-graph.js';
import { loadGraphNotes, loadVocabulary, VAULT_SKIP_DIRS } from './vault-notes.js';
import type { VocabularyError } from './vocabulary.js';

// ─── Public types ─────────────────────────────────────────────────────────────

export interface ReindexOptions {
  /** If true, compute everything but do not write any files. */
  dryRun?: boolean;
  /**
   * If provided, stop writing after this many milliseconds have elapsed since
   * reindex started. Files written so far are consistent (no half-written state).
   * Reports `incompleto: true`.
   */
  deadlineMs?: number;
  /** Override the current time function (for testing). Default: `Date.now`. */
  now?: () => number;
  /**
   * Folder paths whose manual INDEX.md should be renamed to `INDEX (manual).md`
   * and replaced with a generated one. Paths should end with `/` or be bare
   * folder names. Only applies when explicitly passed.
   */
  adoptManual?: string[];
}

export interface ReindexRenameEntry {
  from: string;
  to: string;
}

export interface ReindexReport {
  /** Number of note files scanned (excluding INDEX.md files). */
  notas: number;
  /** Number of vocabulary nodes. */
  temas: number;
  /** Number of notes with no valid topic (unclassified). */
  sinClasificar: number;
  /** Number of unique proposed topics. */
  propuestos: number;
  /** Suggestion entries from computeSuggestions. */
  sugerencias: TopicSuggestion[];
  /** Vault-relative paths of files written (created or updated). */
  archivosEscritos: string[];
  /** Vault-relative paths of derived files deleted (orphaned). */
  archivosEliminados: string[];
  /** Folders whose INDEX.md was manual and was NOT overwritten. */
  indicesManualesOmitidos: string[];
  /** Errors encountered while parsing VOCABULARIO.md. */
  erroresVocabulario: VocabularyError[];
  /** True when the deadline was hit before all files could be written. */
  incompleto: boolean;
  /** Folders whose manual INDEX.md was renamed (when adoptManual is used). */
  adoptados: string[];
  /**
   * Files renamed as part of adoptManual.
   * In dryRun: what would be renamed. Without dryRun: what was renamed.
   */
  renombrados: ReindexRenameEntry[];
}

// ─── VaultReindexer ───────────────────────────────────────────────────────────

export class VaultReindexer {
  constructor(
    private readonly fs: FilesystemPort,
    private readonly vaultDir: string,
  ) {}

  /**
   * Scan the vault, build the knowledge graph, and write only changed files.
   *
   * @param opts - Optional overrides (dryRun, deadlineMs, now, adoptManual).
   * @returns A report describing what was done.
   */
  async reindex(opts: ReindexOptions = {}): Promise<ReindexReport> {
    const dryRun = opts.dryRun ?? false;
    const now = opts.now ?? (() => Date.now());
    const deadline = opts.deadlineMs !== undefined ? now() + opts.deadlineMs : undefined;
    const adoptSet = normaliseAdoptSet(opts.adoptManual ?? []);

    const startedWriting: string[] = [];
    const deleted: string[] = [];
    const indicesManualesOmitidos: string[] = [];
    const erroresVocabulario: VocabularyError[] = [];
    const adoptados: string[] = [];
    const renombrados: ReindexRenameEntry[] = [];
    let incompleto = false;

    // ── 1. Scan notes ────────────────────────────────────────────────────────
    const graphNotes = await loadGraphNotes(this.fs, this.vaultDir);

    // ── 2. Read vocabulary ───────────────────────────────────────────────────
    const { vocabulary, errors: vocabErrors } = await loadVocabulary(this.fs, this.vaultDir);
    erroresVocabulario.push(...vocabErrors);

    // ── 3. Build knowledge graph ─────────────────────────────────────────────
    const graphMap = buildKnowledgeGraph(graphNotes, vocabulary);

    // ── 4. Collect existing derived files in the vault ───────────────────────
    const existingDerived = await this.collectExistingDerived(this.vaultDir);

    // ── 5. Handle adoptManual before writing ─────────────────────────────────
    // Folders whose INDEX.md could not be adopted (conflict) — treat as manual.
    const failedAdoptFolders = new Set<string>();

    if (adoptSet.size > 0) {
      for (const folder of adoptSet) {
        const indexPath = `${folder}/INDEX.md`;
        const manualPath = `${folder}/INDEX (manual).md`;
        const absIndex = joinPath(this.vaultDir, indexPath);
        const absManual = joinPath(this.vaultDir, manualPath);

        if (!(await this.fs.exists(absIndex))) continue;

        const existingContent = await readFileSafe(this.fs, absIndex);
        if (existingContent === null) continue;

        // Check if it's already a generated file (don't adopt generated files)
        if (isChambaGenerated(indexPath, existingContent)) continue;

        // Check if INDEX (manual).md already exists → error, skip and treat as manual
        if (await this.fs.exists(absManual)) {
          erroresVocabulario.push({
            code: 'DUPLICATE_PATH',
            message: `No se puede adoptar "${indexPath}": ya existe "${manualPath}". Renombra o elimina manualmente "${manualPath}" primero.`,
            path: indexPath,
          });
          failedAdoptFolders.add(folder);
          continue;
        }

        if (dryRun) {
          // Just report the plan
          adoptados.push(folder);
          renombrados.push({ from: indexPath, to: manualPath });
        } else {
          // Read bytes, write to new path, remove original
          const bytes = await this.fs.readBytes(absIndex);
          await ensureDir(this.fs, joinPath(this.vaultDir, folder));
          await this.fs.writeBytes(absManual, bytes);
          await this.fs.remove(absIndex);
          adoptados.push(folder);
          renombrados.push({ from: indexPath, to: manualPath });
          existingDerived.delete(indexPath); // No longer exists
        }
      }
    }

    // ── 6. Detect manual INDEX.md files ──────────────────────────────────────
    // For any folder INDEX.md that will be generated, check if a manual one exists.
    for (const [relPath] of [...graphMap.entries()]) {
      if (relPath !== 'INDEX.md' && !relPath.endsWith('/INDEX.md')) continue;
      const absPath = joinPath(this.vaultDir, relPath);
      if (!(await this.fs.exists(absPath))) continue;

      const existing = await readFileSafe(this.fs, absPath);
      if (existing === null) continue;

      // If it's not a generated file, it's manual
      if (!isChambaGenerated(relPath, existing)) {
        const folder = relPath === 'INDEX.md' ? '' : relPath.slice(0, -'/INDEX.md'.length);
        // Adopt if: folder is in adoptSet AND adoption did not fail
        // In dryRun mode, willAdopt=true means: plan shows INDEX.md will be written
        // (i.e. this folder is NOT in indicesManualesOmitidos)
        const willAdopt = adoptSet.has(folder) && !failedAdoptFolders.has(folder);
        if (!willAdopt) {
          // Not adopting (or dry-run or failed adoption) — skip and report
          indicesManualesOmitidos.push(relPath);
          graphMap.delete(relPath); // remove from what we'll write
        }
      }
    }

    // ── 7. Write changed files ────────────────────────────────────────────────
    for (const [relPath, content] of graphMap) {
      if (deadline !== undefined && now() >= deadline) {
        incompleto = true;
        break;
      }

      const absPath = joinPath(this.vaultDir, relPath);

      // Check if content changed
      const existing = await readFileSafe(this.fs, absPath);
      if (existing === content) {
        // No change — skip
        existingDerived.delete(relPath); // not orphaned
        continue;
      }

      existingDerived.delete(relPath); // not orphaned

      if (!dryRun) {
        const dir = dirnameOf(relPath);
        if (dir !== '') {
          await ensureDir(this.fs, joinPath(this.vaultDir, dir));
        }
        await this.fs.writeFile(absPath, content);
      }

      startedWriting.push(relPath);
    }

    // ── 8. Delete orphaned derived files ────────────────────────────────────
    // existingDerived now contains only files that were NOT in the new graph output
    // (i.e., orphaned). Only delete if isChambaGenerated.
    // M2: skip deletion if write was incomplete (incompleto=true) to avoid
    // deleting files whose corresponding generated output was never written.
    for (const relPath of incompleto ? [] : existingDerived) {
      const absPath = joinPath(this.vaultDir, relPath);
      const content = await readFileSafe(this.fs, absPath);
      if (content === null) continue;
      if (!isChambaGenerated(relPath, content)) continue;

      if (!dryRun) {
        try {
          await this.fs.remove(absPath);
        } catch {
          // If deletion fails, skip — don't crash
          continue;
        }
      }
      deleted.push(relPath);
    }

    // ── 9. Build report ───────────────────────────────────────────────────────
    const sugerencias = computeSuggestions(graphNotes, vocabulary);

    // Count unclassified and proposed
    let sinClasificar = 0;
    const proposedSet = new Set<string>();
    for (const n of graphNotes) {
      if (vocabulary === null) {
        sinClasificar++;
      } else {
        const hasValid = (n.metadata.tags ?? []).some(
          (t) => t.startsWith('tema/') && vocabulary.nodes.has(t.slice('tema/'.length)),
        );
        if (!hasValid) sinClasificar++;
      }
      for (const p of n.metadata.temas_propuestos ?? []) proposedSet.add(p);
      if (vocabulary !== null) {
        for (const t of n.metadata.tags ?? []) {
          if (t.startsWith('tema/')) {
            const slug = t.slice('tema/'.length);
            if (!vocabulary.nodes.has(slug)) proposedSet.add(slug);
          }
        }
      }
    }

    return {
      notas: graphNotes.length,
      temas: vocabulary?.nodes.size ?? 0,
      sinClasificar,
      propuestos: proposedSet.size,
      sugerencias,
      archivosEscritos: startedWriting.sort(),
      archivosEliminados: deleted.sort(),
      indicesManualesOmitidos: indicesManualesOmitidos.sort(),
      erroresVocabulario,
      incompleto,
      adoptados: adoptados.sort(),
      renombrados,
    };
  }

  // ─── Private helpers ───────────────────────────────────────────────────────

  /**
   * Collect existing derived files (paths matching isDerivedPathPattern) in the vault.
   * Returns a Set of vault-relative paths.
   */
  private async collectExistingDerived(absVaultDir: string): Promise<Set<string>> {
    const result = new Set<string>();
    await this.collectDerivedRecursive(absVaultDir, '', result);
    return result;
  }

  private async collectDerivedRecursive(
    absDir: string,
    relPrefix: string,
    result: Set<string>,
  ): Promise<void> {
    let entries: DirEntry[];
    try {
      entries = await this.fs.readDir(absDir);
    } catch {
      return;
    }

    for (const entry of entries) {
      const name = entry.name;
      const relPath = relPrefix === '' ? name : `${relPrefix}/${name}`;

      if (entry.isDirectory) {
        // M1: apply same skip-set as scanNotes (via shared VAULT_SKIP_DIRS)
        const topPart = relPath.split('/')[0] ?? '';
        if (VAULT_SKIP_DIRS.has(topPart.toLowerCase())) continue;
        if (name.startsWith('.')) continue; // skip dotdirs
        if (isTaskEvidencePath(relPath)) continue; // B8: evidence subtree, never derived files
        await this.collectDerivedRecursive(`${absDir}/${name}`, relPath, result);
      } else if (entry.isFile) {
        if (isDerivedPathPattern(relPath)) {
          result.add(relPath);
        }
      }
    }
  }
}

// ─── Local utilities ──────────────────────────────────────────────────────────

function joinPath(...parts: string[]): string {
  return parts
    .filter((p) => p.length > 0)
    .join('/')
    .replace(/\/{2,}/g, '/');
}

function dirnameOf(path: string): string {
  const idx = path.lastIndexOf('/');
  return idx === -1 ? '' : path.slice(0, idx);
}

async function readFileSafe(fs: FilesystemPort, absPath: string): Promise<string | null> {
  try {
    return await fs.readFile(absPath);
  } catch {
    return null;
  }
}

async function ensureDir(fs: FilesystemPort, absDir: string): Promise<void> {
  try {
    await fs.mkdir(absDir);
  } catch {
    // Ignore — dir may already exist
  }
}

function normaliseAdoptSet(adoptManual: string[]): Set<string> {
  const s = new Set<string>();
  for (const f of adoptManual) {
    // Normalise: strip trailing slash
    const norm = f.replace(/\/+$/, '').replace(/\\/g, '/').normalize('NFC');
    if (norm) s.add(norm);
  }
  return s;
}
